const GC = {"Pommiers": ["🍎", "#c0392b"], "Poiriers": ["🍐", "#7a8a17"], "Nashis": ["🍏", "#3f8f5a"], "Pruniers": ["🫐", "#6c3f8f"], "Cerisiers": ["🍒", "#a8203a"], "Pêchers et abricotier": ["🍑", "#d9702a"], "Figuiers": ["🌿", "#6b4a63"], "Vignes": ["🍇", "#7a3b69"], "Petits fruits": ["🫐", "#3a5aa8"], "Kiwi et kiwaï": ["🥝", "#4a8f2f"], "Kakis": ["🍊", "#d4791a"], "Pawpaw": ["🥭", "#8a7a22"], "Fruits à coque": ["🌰", "#8a5a2b"], "Autres fruitiers": ["🌳", "#2f7d6d"], "Fleurs de printemps (taille juste après la floraison)": ["🌸", "#c2538d"], "Fleurs d'été et d'automne (taille en mars)": ["🌻", "#c9791a"], "Persistants": ["🌲", "#2e6b4a"], "Autres arbustes": ["🌿", "#4f7f3a"], "Grimpantes": ["🌺", "#7b5ba6"], "Graminées et bambous": ["🎋", "#8a8f1f"], "Arbre": ["🌳", "#5b6b3a"]};
const RF = [["Air et lumière", "Un arbre aéré sèche vite après la pluie : les champignons (tavelure, oïdium) ont besoin de feuilles mouillées."], ["Hygiène", "Ramasse feuilles et fruits malades, désinfecte tes outils (alcool 70°). Les maladies hivernent dedans."], ["Sol vivant", "Compost, paillis (sans toucher le tronc), engrais verts : un arbre bien nourri résiste mieux."], ["Auxiliaires", "Nichoirs, haies fleuries, tas de bois : mésanges, coccinelles et chrysopes mangent tes ravageurs."], ["Prévenir plutôt que guérir", "Les traitements naturels agissent avant l'infection, pas après. Le timing compte plus que la dose."], ["Observer chaque semaine", "Dix minutes au verger au printemps repèrent un problème quand il se règle d'un geste."]];
const SV = [["Pommier", "Tavelure, carpocapse (ver), pucerons cendrés, oïdium, chancre", "Feuilles ramassées en automne, prêle au printemps, pièges, taille aérée. Variétés résistantes si tu replantes (Topaz, Florina…)"], ["Poirier", "Tavelure, psylle, carpocapse, feu bactérien", "Idem pommier ; surveille les rameaux flétris en juin"], ["Prunier", "Moniliose, ver des prunes, chancre bactérien, maladie du plomb", "Taille en été seulement, fruits momifiés retirés, pièges à phéromones"], ["Nashi", "Tavelure, moniliose, feu bactérien", "Comme le pommier ; éclaircir pour éviter des branches surchargées"], ["Néflier", "Très rustique ; feu bactérien et moniliose rares", "Taille légère, rien de plus"], ["Kiwi / kiwaï", "Gel tardif, pourriture des racines, chancre bactérien", "Sol drainé, paillis épais, voile au printemps. Il faut un pied mâle pour 6–8 femelles (sauf variétés autofertiles)"], ["Vigne", "Mildiou, oïdium, black rot, botrytis", "Palissage, effeuillage côté soleil du matin, lait dilué et prêle"], ["Pawpaw", "Presque aucune maladie", "Deux variétés différentes pour la pollinisation, ombre les 2 premières années"], ["Kaki", "Chute de fruits, cochenilles", "Arrosage régulier en été, peu d'engrais azoté"], ["Cerisier (Early Rivers)", "Moniliose, pucerons noirs, mouche suzukii, fruits éclatés par la pluie", "Filet, cueillette rapide, taille juste après récolte, fruits abîmés retirés"], ["Pêchers (Redhaven, Reine des Vergers)", "Cloque (la principale), pucerons verts, moniliose, oïdium", "Prêle et argile avant les bourgeons, abri de la pluie, feuilles cloquées retirées, éclaircissage"], ["Abricotier", "Gel des fleurs, moniliose, gommose, dépérissement de branches", "Place abritée au sud, voile, taille d'été seulement"], ["Figuier (Brown Turkey)", "Presque aucune maladie ; gel des rameaux, chute de figues si manque d'eau", "Paillis, abri les premiers hivers, arrosage régulier"], ["Framboisier (Autumn Bliss)", "Botrytis, ver du framboisier, drageons envahissants", "Cannes aérées, taille à ras en février, cueillette fréquente"], ["Argousier", "Presque aucune ; drageons, épines", "Plein soleil, sol drainé, mâles et femelles"], ["Arbousier, feijoa", "Gel des jeunes plants, taches sur feuilles en hiver humide", "Paillis, voile, sol drainé"], ["Amélanchier, sorbier", "Feu bactérien (comme les poiriers)", "Surveille les rameaux flétris en juin"], ["Goji, aronia, elaeagnus, poivre du Japon", "Quasi aucun problème", "Sol drainé, taille légère, récolte à temps"]];
const TR = [["Décoction de prêle", "champignons (tavelure, oïdium, moniliose)", "1 kg de prêle fraîche (ou 150 g séchée) dans 10 L d'eau, macérer 24 h, bouillir 30 min, filtrer. Diluer 1 volume pour 5 d'eau."], ["Purin d'ortie", "pucerons ; stimule les plantes", "1 kg d'orties dans 10 L d'eau de pluie, 5 à 7 jours en remuant. Diluer à 10 % pour pulvériser."], ["Savon noir", "pucerons, cochenilles", "2 cuillères à soupe par litre d'eau tiède, en pulvérisation directe sur les colonies."], ["Lait écrémé", "oïdium, surtout sur la vigne", "1 volume de lait pour 9 volumes d'eau."], ["Argile blanche (kaolin)", "psylle, pontes d'insectes", "Environ 30 g par litre : un film minéral qui gêne les ravageurs."]];
const PGC = [["Pas de bêchage, jamais", "On ne retourne pas le sol : on le nourrit par le dessus. Vers, champignons et micro-organismes font le travail, la structure naturelle du sol reste intacte, il y a beaucoup moins de désherbage. Tu peux marcher sur le sol de temps en temps sans souci"], ["Du compost en couverture", "C'est la base de la méthode de Charles Dowding : environ 5 cm de compost mûr étalés chaque année sur les planches (automne-hiver, ou début de printemps). Pour une planche neuve, vise 10 à 15 cm. Les semis et plants se font directement dans cette couche. Même 1 cm de compost fait du bien au sol"], ["Planches de 1,20 m", "Cette largeur permet d'atteindre le milieu depuis les deux côtés sans marcher dessus. Chemins de 30 à 45 cm. Les bords en bois (planches de 15 cm) aident au début mais ne sont pas obligatoires"], ["Le carton contre les mauvaises herbes", "Sur herbe, chiendent ou liseron : carton sans adhésif ni encre, bien chevauché, recouvert de 15 cm de compost. Sur un sol peu envahi, le carton est inutile. Dans les chemins, le carton tient 6 à 9 mois : ajoute une couche tous les 3 mois, puis du broyat ou des copeaux par-dessus"], ["Semer en godets, planter serré", "On sème en plaques ou godets, plusieurs graines par alvéole (environ 2,5 cm), puis on repique la touffe 2 à 4 semaines plus tard. Les plants sont déjà forts face aux limaces, on gagne du temps au potager, et on plante assez serré pour que les feuilles couvrent le sol"], ["Jamais de sol nu", "Dès qu'une culture se termine, replante ou sème tout de suite (salade après pommes de terre, par exemple) ou couvre avec du compost, de la paille ou un engrais vert (moutarde, phacélie). Un sol couvert garde son humidité, sa vie et ses nutriments"], ["Arroser peu, mais bien", "Le compost en couverture retient l'eau. Arrose au pied, le matin, en profondeur et moins souvent. Les moments critiques sont les 2 semaines après un repiquage et les périodes sèches. Un paillage de tontes séchées en été limite l'évaporation"], ["Limaces : une lutte constante", "Ramasse-les le soir ou à l'aube, supprime les cachettes (planches, pierres, tas d'herbe), garde le sol propre autour des jeunes plants et plante des plants vigoureux. Hérissons, crapauds, oiseaux et carabes sont tes alliés : prévois une mare, un tas de bois, des zones sauvages"], ["Une rotation simple", "Change la famille de légumes à chaque planche d'une année à l'autre : pommes de terre et tomates, choux, carottes et racines, oignons et ail, légumineuses. Ça limite maladies et épuisement du sol. Note ton plan chaque année dans un carnet"], ["Les repères de ton climat (région d'Ath)", "Dernières gelées en général entre mi-avril et début mai : les saints de glace (11-13 mai) sont le repère pour tomates, courgettes, haricots et poivrons. Premières gelées fin octobre à novembre. Un voile d'hivernage ou un petit tunnel prolonge la saison de plusieurs semaines"]];
const LG = [["Pommes de terre", "#a8742f", "🥔", "La reine du jardin : généreuse et facile", "Solanacées", "2", "☀️ Plein soleil", "2", ",,P,P,P,R,R,R,R,,,", "Fais germer les plants en février, à la lumière et au frais : des germes courts et trapus.\nPlante de mi-mars à avril, germes vers le haut, tous les 30-35 cm (rangs à 60 cm), posés sur le sol et recouverts de 5 cm de compost ou de paille.\nQuand les fanes font 20 cm, butte avec du compost ou de la paille. Arrose seulement par temps sec, surtout à la floraison.\nRécolte les primeurs 10 à 12 semaines après la plantation. Pour stocker : fanes jaunies, quelques heures de séchage à l'ombre, puis cave, au noir et au frais.", "Mildiou (taches brunes, fanes qui noircissent) | Plants précoces et variétés résistantes, rangs aérés, feuilles jamais mouillées. Si les fanes sont atteintes, coupe-les et évacue-les : tu peux récolter 2 semaines plus tard\nDoryphores | Ramasse adultes, larves et pontes orange sous les feuilles chaque semaine ; un paillage épais les gêne\nGale (croûtes sur la peau) | Évite chaux et fumier frais, garde le sol humide quand les tubercules grossissent, variétés résistantes ; elles restent comestibles", "Haricots, œillets d'Inde, chou-rave", "Tomates, courges, tournesols", "Pose les plants germés sur le sol nu ou le carton et couvre de 15 cm de compost ou de paille : récolte sans fourche, il suffit d'écarter la couche."], ["Carottes", "#d96a0f", "🥕", "Croquantes, si on leur offre un sol fin", "Apiacées", "2", "☀️ Plein soleil", "2", ",,S,S,S,SR,SR,R,R,R,R,", "Prépare un sol fin et meuble, sans cailloux, avec du compost bien mûr tamisé (le fumier frais donne des carottes fourchues).\nSème de mars à juillet en place, en lignes à 20 cm, graines fines mélangées à du sable. Couvre d'une planche jusqu'à la levée (2-3 semaines) en gardant humide.\nÉclaircis à 3-4 cm le soir en coupant au ciseau, puis pose aussitôt un voile anti-insectes. Arrose régulièrement pour éviter les racines fendues.\nRécolte de juin à novembre, au fur et à mesure. Stockage : cave dans du sable, ou laisse en terre sous paille jusqu'aux fortes gelées.", "Mouche de la carotte (galeries dans les racines) | Voile anti-insectes dès le semis, un rang de poireaux ou d'oignons à côté, éclaircissage le soir\nPourriture et alternaria (taches noires) | Rotation de 4 ans, sol drainé, pas d'excès d'eau, retire les feuilles atteintes\nCarottes fourchues ou fendues | Pas de fumier frais ni de cailloux, arrosage régulier, sol meuble en profondeur", "Poireaux, oignons, ciboulette, radis, romarin", "Aneth, panais (mêmes maladies)", "Sème sur 5 cm de compost tamisé étalé sur la planche : le sol reste fin et les racines poussent droites."], ["Betteraves", "#8e2a63", "🟣", "Rouge profond, racine et feuilles se mangent", "Amaranthacées", "1", "☀️ Soleil ou mi-ombre", "2", ",,,S,SP,SP,SR,R,R,R,,", "Sème d'avril à juillet, en place (2 cm, rangs à 25 cm) ou en godets, 2 à 3 graines par alvéole (chaque graine est un petit paquet de graines).\nRepique les godets à 4-5 semaines en gardant la touffe entière, à 10 cm d'écart.\nArrose régulièrement au début, paille légère. Éclaircis en cueillant les plus petites : les feuilles se mangent.\nRécolte de juillet à octobre à 5-8 cm de diamètre, plus grosses elles deviennent ligneuses. Stockage en cave dans du sable ou en cageot au frais.", "Cercosporiose (petites taches rondes sur les feuilles) | Rotation, sol aéré, retire les feuilles tachées ; la racine reste bonne\nPucerons noirs | Jet d'eau, savon noir dilué, coccinelles ; ne les plante pas à côté des fèves\nRacines dures ou creuses | Arrosage irrégulier : arrose régulièrement, paille, récolte à 5-8 cm", "Oignons, choux, laitues, haricots nains", "Haricots à rames, moutarde", "Sème 2-3 graines par godet et ne sépare jamais la touffe : plus d'éclaircissage, et la place est mieux utilisée."], ["Oignons et échalotes", "#b8821f", "🧅", "À planter, à sécher, ils se gardent tout l'hiver", "Amaryllidacées", "2", "☀️ Plein soleil", "1", "S,S,SP,P,,,,R,R,,,", "Sème fin janvier-février en godets (4-5 graines par alvéole) sous abri, ou plante des bulbilles en mars-avril sans enterrer le bulbe.\nRepique les touffes en mars-avril à 20-25 cm, sans enterrer le collet. Le compost en couverture limite les herbes.\nDésherbe à la main au début, ils n'aiment pas la concurrence. Arrose seulement en sécheresse.\nRécolte en août-septembre quand les feuilles se couchent et jaunissent. Fais sécher 2 à 3 semaines au soleil ou sous abri, puis tresse ou mets en filet, au sec.", "Mildiou de l'oignon (feuilles grises qui jaunissent) | Rotation de 4 ans, espace aéré, retire les plants atteints\nMouche de l'oignon | Voile anti-insectes dès la plantation, alterne avec des carottes\nPourriture blanche (duvet blanc, bulbes pourris) | Rotation d'au moins 4 ans, jamais d'oignon ni d'ail au même endroit ; évacue les plants atteints, ne les composte pas", "Carottes, betteraves, laitues, fraisiers", "Pois, haricots, fèves", "Plantés sur 5 cm de compost mûr, les oignons n'ont presque pas d'herbes : le collet doit rester visible."], ["Ail", "#8d7f60", "🧄", "Planté à l'automne, récolté à l'été", "Amaryllidacées", "1", "☀️ Plein soleil", "1", ",P,,,,R,R,,,P,P,", "Plante les plus grosses gousses, pointe en haut, d'octobre à novembre (ou en février), à 3 cm de profondeur, tous les 15 cm.\nCouvre d'un peu de paille ou de compost l'hiver. Désherbe tôt au printemps.\nArrête d'arroser vers la mi-mai : l'ail veut finir au sec. Enlève les hampes florales si tu en as (elles se mangent).\nRécolte en juin-juillet quand les feuilles jaunissent aux deux tiers. Fais sécher 2-3 semaines à l'ombre aérée, puis tresse ou garde en filet, au sec.", "Rouille (pustules orange sur les feuilles) | Rotation de 4 ans, aération, pas d'excès d'azote ni de sol détrempé ; les gousses restent comestibles\nTeigne du poireau | Voile anti-insectes en avril-mai et en septembre, rotation\nPourriture blanche | Rotation d'au moins 4 ans, ne replante pas d'ail ni d'oignon au même endroit, sol drainé", "Carottes, tomates, fraisiers, rosiers", "Pois, haricots, fèves", "Enfonce simplement chaque gousse de 3 cm dans une couche de 5 cm de compost : aucun travail du sol."], ["Poireaux", "#2e8b57", "🌿", "Le légume d'hiver qui ne craint pas le froid", "Amaryllidacées", "2", "☀️ Plein soleil", "2", "R,R,SR,S,S,P,P,,,R,R,R", "Sème de mars à mai en godets ou en pépinière, 4 à 5 graines par alvéole.\nRepique en juin-juillet quand les plants font la taille d'un crayon : fais un trou de 15 cm au plantoir et laisse tomber le plant, sans reboucher (l'eau le fera).\nArrose bien la première semaine, puis paille. Ils poussent tout l'été sans souci.\nRécolte de septembre à mars à la fourche, à la demande. Ils tiennent au gel et se gardent bien sur place.", "Teigne du poireau (galeries, feuilles trouées) | Voile fin anti-insectes d'avril à mai et d'août à octobre, rotation\nRouille (taches orange) | Rotation de 4 ans, aération, pas trop d'azote ; coupe les feuilles atteintes\nMouche mineuse | Voile fin, retire les feuilles très abîmées", "Carottes, céleri, fraisiers, betteraves", "Pois, haricots, fèves", "Les trous au plantoir blanchissent naturellement le fût : plus besoin de butter."], ["Choux", "#3f8f4f", "🥬", "Pommé, kale, brocoli : des légumes pour toutes les saisons", "Brassicacées", "2", "☀️ Soleil", "2", "R,R,R,S,SP,P,P,,R,R,R,R", "Sème d'avril à mai en godets sous abri, 2 graines par alvéole et garde la plus belle. Chou-fleur et brocoli : mars à mai.\nRepique de mai à juillet en enterrant jusqu'aux premières feuilles, à 40-60 cm, sur sol ferme (ils n'aiment pas la terre ameublie). Pose le filet tout de suite.\nArrose bien jusqu'à la reprise, puis paille. Un filet anti-insectes sur arceaux est indispensable contre piérides et pigeons.\nKale : cueille feuille à feuille dès l'automne. Chou pommé et choux de Bruxelles : de septembre à mars, ils sont plus sucrés après les premières gelées.", "Piérides (chenilles qui dévorent les feuilles) | Filet à mailles fines dès la plantation, ramasse chenilles et pontes jaunes sous les feuilles\nAltises (petits trous), pucerons cendrés | Arrosage et paillage, filet, savon noir dilué sur les pucerons\nHernie du chou (racines déformées) | Rotation d'au moins 4 ans, sol non acide (un peu de lithothamne ou de cendres de bois), arrache et évacue les plants atteints", "Capucines, aneth, céleri, betteraves, camomille", "Tomates, fraisiers", "Compost en couverture sur sol tassé : les choux repiqués en sol ferme font des pommes plus serrées."], ["Salades", "#4a9a3a", "🥗", "Du frais toute l'année, en godets", "Astéracées", "1", "⛅ Soleil ou mi-ombre", "2", "R,S,SP,SP,SPR,SPR,SPR,SPR,SPR,PR,R,R", "Sème toute l'année en godets (de février à septembre), 3-4 graines par alvéole juste recouvertes : la laitue germe à la lumière.\nRepique en touffes à 3-4 semaines : 25-30 cm pour les laitues pommées, 15 cm pour les salades à couper.\nArrose au pied, tôt le matin. En été, un peu d'ombre limite la montée en graine.\nCueille feuille à feuille ou coupe à 3 cm du sol (elles repoussent), et sème une série toutes les 3 semaines. Mâche, roquette, mizuna : de septembre à mars sous tunnel ou voile.", "Limaces et escargots | Ramasse le soir, supprime les cachettes, pièges à bière enterrés, plants robustes en godets, hérissons et crapauds\nPucerons | Jet d'eau, savon noir dilué, coccinelles, fleurs mellifères\nPourriture du collet, mildiou | Ne plante pas trop profond, aère, arrose au pied, rotation", "Radis, carottes, fraisiers, poireaux, ciboulette", "Persil, céleri", "Coupe tes salades à 3 cm du sol : elles repoussent 2 à 3 fois sur une même planche."], ["Épinards et blettes", "#2f8f3a", "🍃", "Vertes et vitaminées, de mars à novembre", "Amaranthacées", "1", "⛅ Soleil ou mi-ombre", "2", ",,S,S,SR,R,R,S,SR,R,R,", "Épinards : sème de mars à mai et de fin août à septembre, en place (2 cm), lignes à 25 cm. Blettes : avril-juin en godets, 2-3 graines.\nRepique les blettes en mai tous les 30 cm. Éclaircis les épinards à 10 cm.\nArrose régulièrement : les épinards montent vite en graine par temps chaud et sec. Paille légère.\nCueille les feuilles extérieures des épinards (6-8 semaines après le semis) et les côtes des blettes : elles repoussent jusqu'à l'automne.", "Pucerons, limaces | Jet d'eau, savon noir dilué, ramassage au crépuscule\nMildiou des épinards | Semis espacés, variétés résistantes, pas d'eau sur les feuilles\nMouche mineuse (galeries blanches) | Voile anti-insectes, retire les feuilles atteintes", "Fraisiers, choux, haricots, radis", "Betteraves (même famille)", "En été, les blettes remplacent les épinards : elles ne montent pas en graine et produisent jusqu'aux gelées."], ["Radis", "#c2305f", "🔴", "Prêt en 4 semaines : le légume des impatients", "Brassicacées", "1", "⛅ Soleil ou mi-ombre", "2", ",,S,SR,SR,SR,SR,SR,SR,R,,", "Sème de mars à septembre en place, 1-2 cm de profondeur, lignes à 15 cm, de préférence à mi-ombre en été.\nÉclaircis à 3 cm quand les plants ont 2-3 feuilles.\nArrose régulièrement et légèrement : un manque d'eau rend les radis piquants et creux. Sème toutes les 2 semaines.\nCueille dès 4 à 6 semaines (2-3 cm de diamètre). Radis noirs et d'hiver : semés en juillet-août, récoltés à l'automne.", "Altises (petits trous dans les feuilles) | Arrosage régulier, voile anti-insectes, paillage\nLimaces | Pièges à bière, ramassage, récolte rapide\nRadis creux ou fourchus | Sol léger, arrosage régulier, ne les laisse pas trop grossir", "Carottes, laitues, épinards, concombres", "Choux et autres crucifères", "Sème les radis dans le même rang que les carottes : ils marquent le rang et sont récoltés avant que les carottes ne lèvent."], ["Pois", "#4a9b3a", "🟢", "Doux et croquants, à manger frais", "Fabacées", "1", "☀️ Soleil", "2", ",,S,S,SR,R,R,,,,,", "Sème de mars à mai en place (3-4 cm de profondeur, 5 cm entre graines) ou en godets sous abri en février-mars.\nPose tuteurs, branches ou filet dès la levée : les vrilles s'y accrochent.\nArrose à la floraison et à la formation des gousses, paille entre les rangs.\nCueille régulièrement de mai à juillet. Les petits pois frais se mangent le jour même, les mange-tout avant que les grains ne gonflent.", "Pucerons verts | Jet d'eau, savon noir dilué, coccinelles et syrphes\nBruches (petits trous dans les pois secs) | Congèle les graines sèches 2 jours avant de les stocker\nOïdium (poudre blanche) | Sème tôt, aère, arrose le pied ; lait dilué (1 volume pour 9 d'eau) en pulvérisation", "Carottes, navets, radis, laitues", "Ail, oignons, poireaux", "Les pois enrichissent le sol en azote : après la récolte, coupe les tiges au ras du sol et laisse les racines."], ["Fèves", "#7ea84a", "🫘", "Les premières du potager", "Fabacées", "1", "☀️ Soleil", "2", ",S,S,,R,R,,,,S,S,", "Sème en octobre-novembre (variétés d'hiver, 5 cm de profondeur) ou en février-mars, 20 cm entre graines.\nTuteure avec des cordes ou des cannes quand elles grandissent : les tiges sont hautes.\nPince la tête dès que les premières gousses se forment : cela limite les pucerons noirs.\nRécolte en mai-juin quand les gousses sont bien remplies mais encore tendres. Écosse et mange vite, ou congèle.", "Pucerons noirs | Pince les têtes, jet d'eau, savon noir dilué, capucines autour comme appât\nBruches de la fève | Congèle les graines sèches, ne ressème pas de graines trouées\nRouille et taches chocolat | Rangs espacés, semis d'automne, rotation", "Pommes de terre, carottes, choux, maïs", "Ail, oignons, poireaux", "Une fève d'automne couvre le sol l'hiver : après la récolte, coupe-la au ras du sol et laisse les racines nourrir le sol."], ["Haricots", "#43a047", "🫛", "Le légume qui adore la chaleur", "Fabacées", "1", "☀️ Plein soleil", "2", ",,,,S,S,SR,R,R,R,,", "Sème de mai à juillet, après les saints de glace, en place (2-3 cm, 5 cm entre graines, rangs à 40 cm) ou en godets.\nHaricots à rames : tuteurs de 2 m, par exemple un tipi de 3-4 cannes. Haricots nains : rien à faire.\nArrose au pied, surtout à la floraison. Paille légère pour garder l'humidité.\nCueille les gousses jeunes dès juillet : plus tu cueilles, plus il en vient. Pour les secs, laisse sécher les gousses sur la plante.", "Limaces sur jeunes plants | Plants robustes issus de godets, pièges à bière, ramassage\nPucerons noirs | Jet d'eau, savon noir dilué, pince les têtes si besoin\nAnthracnose (taches noires sur gousses) | Graines saines, rotation, ne travaille pas dans les plants mouillés", "Carottes, concombres, pommes de terre, sarriette", "Ail, oignons, poireaux, fenouil", "Un tipi de haricots à rames au milieu de la planche donne beaucoup de récolte sur peu de place."], ["Courgettes et courges", "#e8761c", "🎃", "Une plante, des dizaines de légumes", "Cucurbitacées", "1", "☀️ Plein soleil", "3", ",,,S,SP,P,R,R,R,R,,", "Sème en avril en godets sous abri (2 graines posées à plat, vers 18 °C), garde le plus beau plant.\nPlante après les saints de glace (fin mai) sur une bonne couche de compost, à 1 m d'écart. Protège-les au début contre limaces et froid.\nArrose au pied abondamment, 1 à 2 fois par semaine. Paille pour garder l'eau et protéger les fruits du sol.\nCourgettes : cueille jeunes (15-20 cm) tous les 2-3 jours. Courges : récolte à l'automne avant les gelées, queue liégeuse ; fais sécher 2 semaines au soleil et stocke au sec.", "Oïdium (feutrage blanc) | Arrose au pied, aère, lait dilué (1 volume pour 9 d'eau) en pulvérisation, supprime les feuilles très atteintes\nLimaces | Plants robustes issus de godets, pièges à bière, ramassage\nVirus de la mosaïque | Retire et évacue les plants atteints, lutte contre les pucerons, ne garde pas les graines", "Capucines, maïs, haricots, bourrache", "Pommes de terre", "Plante-les sur ton tas de compost ou dans un trou de compost bien mûr : elles adorent la chaleur et la richesse."], ["Tomates", "#d9382f", "🍅", "La star de l'été, un peu capricieuse", "Solanacées", "2", "☀️ Plein soleil, abri conseillé", "2", ",,S,S,P,P,R,R,R,R,,", "Sème en mars-avril en godets vers 20 °C, sous abri lumineux, puis repique en godets individuels aux premières vraies feuilles.\nPlante fin mai (mi-mai sous serre) en enterrant la tige jusqu'aux premières feuilles : elle fera de nouvelles racines. Tuteur solide dès la plantation.\nPince les gourmands chaque semaine, arrose au pied (jamais sur les feuilles), paille. Étête fin juillet-août.\nRécolte de juillet à octobre quand les fruits sont bien colorés. Avant les gelées, cueille les verts et laisse-les mûrir à l'intérieur.", "Mildiou (taches brunes, fruits qui pourrissent) | Variétés résistantes, abri de pluie (serre ou tunnel), plants espacés, feuilles jamais mouillées, retire les feuilles basses ; décoction de prêle en préventif\nPourriture apicale (fond noir) | Arrosage régulier, paillage, compost en couverture, évite les à-coups d'eau\nPucerons et aleurodes | Œillets d'Inde et basilic à côté, savon noir dilué, coccinelles", "Basilic, œillets d'Inde, carottes, persil, ail", "Pommes de terre, fenouil, choux", "Plante sur 10 cm de compost mûr et ajoute 5 cm de paille : pas d'engrais, moins d'éclaboussures donc moins de mildiou."], ["Concombres", "#3f9f4a", "🥒", "Frais et croquant, à l'abri", "Cucurbitacées", "2", "☀️ Soleil, abri conseillé", "3", ",,,S,SP,P,R,R,R,,,", "Sème en avril-mai en godets au chaud (graines à plat, 20 °C), et plante fin mai sous serre ou à l'abri.\nFais-les grimper sur un tuteur ou un grillage : gain de place et fruits propres. Pince après la 5e feuille.\nArrose abondamment au pied : ils ont besoin de beaucoup d'eau, mais évite le feuillage. Paille.\nCueille de juillet à septembre tous les 2-3 jours, fermes et de taille normale ; plus tu récoltes, plus ils produisent.", "Oïdium | Aère, arrose au pied, lait dilué (1 volume pour 9 d'eau), variétés résistantes\nPucerons, araignées rouges (air sec) | Brumise le feuillage le matin, savon noir dilué, coccinelles\nMildiou du concombre (taches jaunes anguleuses) | Variétés résistantes, aération, pas d'eau sur les feuilles", "Haricots, radis, laitues, aneth, tournesol", "Pommes de terre, sauge, menthe", "Un grillage ou un tipi garde les concombres droits et propres, et l'air circule : moins de maladies."], ["Poivrons et aubergines", "#c62828", "🫑", "Les chaleureux : la serre aide beaucoup chez nous", "Solanacées", "3", "☀️ Plein soleil, serre ou tunnel", "2", ",,S,S,P,P,R,R,R,R,,", "Sème en mars au chaud (22-25 °C) en godets : la croissance est lente. Repique en godets individuels.\nPlante fin mai-début juin sous serre ou tunnel (dehors : coin très chaud et abrité), à 50 cm. Tuteure les aubergines.\nArrose au pied régulièrement, paille. Pince l'aubergine à 5-6 fruits pour qu'ils grossissent.\nRécolte d'août à octobre. Les poivrons verts se mangent mais sont plus doux rouges ; les aubergines quand la peau est brillante et ferme.", "Pucerons, aleurodes | Savon noir dilué, coccinelles, œillets d'Inde et basilic à proximité\nAraignées rouges (air sec sous serre) | Aère, brumise le feuillage, savon noir dilué\nPourriture apicale | Arrosage régulier, paillage", "Basilic, œillets d'Inde, carottes, oignons", "Fenouil, pommes de terre à proximité", "Un petit tunnel ou une serre fait la différence : quelques degrés de plus suffisent à mûrir les poivrons."], ["Panais et céleri-rave", "#8d7a45", "🤍", "Les racines de l'hiver", "Apiacées", "2", "☀️ Soleil", "2", "R,R,S,S,SP,,,,,R,R,R", "Panais : sème en place de mars à mai avec des graines de l'année (elles perdent vite leur pouvoir germinatif), lignes à 30 cm. Céleri-rave : godets en mars-avril, au chaud.\nÉclaircis le panais à 10-15 cm. Repique le céleri-rave en mai à 40 cm, collet à fleur de sol.\nArrose régulièrement, paille épaisse. Retire les feuilles basses abîmées du céleri-rave.\nRécolte d'octobre à mars à la fourche : les gelées améliorent le goût du panais. Stocke en cave dans du sable, ou laisse en terre sous paille.", "Rouille et septoriose du céleri (taches brunes) | Rotation de 4 ans, aération, retire les feuilles atteintes\nMouche du céleri (galeries dans les feuilles) | Voile anti-insectes, retire les feuilles atteintes\nChancre du panais (taches noires sur la racine) | Rotation, sol bien drainé, variétés résistantes, ne blesse pas les racines", "Poireaux, oignons, laitues, haricots nains", "Carottes (mêmes maladies), pommes de terre", "Le panais germe lentement : sème-le avec quelques radis pour marquer le rang, et garde le sol humide."]];
